def topo_sort(graph):
    out, state = [], {}

    def visit(n):
        if state.get(n) == 1:
            raise ValueError("cycle")
        if state.get(n) == 2:
            return
        state[n] = 1
        for d in graph[n]:
            visit(d)
        state[n] = 2
        out.append(n)

    for n in graph:
        visit(n)
    return out

